(function () {
	// Brand values come from agileclix_brand.js, generated by brand/apply.py.
	const BRAND = window.AGILECLIX_BRAND;
	if (!BRAND) {
		console.warn("AgileClix branding: agileclix_brand.js not loaded; run brand/apply.py and rebuild assets.");
		return;
	}
	const LOGO = BRAND.logo;
	const APP_NAME = BRAND.name;
	const TAGLINE = BRAND.tagline;
	const PUBLISHER = BRAND.publisher;
	// Longest keys first so "Frappe Framework" is replaced before "Frappe".
	const REBRAND_MAP = Object.fromEntries(
		Object.entries(BRAND.replace || {}).sort((a, b) => b[0].length - a[0].length)
	);

	const LOGO_SELECTORS =
		".app-logo img, .navbar-brand img, .sidebar-brand img, .page-card-head img, " +
		".brand-logo img, .navbar-home img, .desk-sidebar .app-logo img, " +
		".widget-app-icon img, .app-icon img, .standard-image, " +
		"img[src*='erpnext'], img[src*='frappe-framework'], img[src*='frappe.svg']";

	const TEXT_ROOTS = "header.navbar, .layout-main, .desk-sidebar, .list-sidebar, .page-head, .modal";

	let applyScheduled = false;

	function escapeHtml(text) {
		const span = document.createElement("span");
		span.textContent = text;
		return span.innerHTML;
	}

	function markBranded() {
		document.documentElement.classList.add("agileclix-branded");
		document.body.classList.add("agileclix-branded");
	}

	function swapLogos(root) {
		(root || document).querySelectorAll(LOGO_SELECTORS).forEach((img) => {
			if (!img.src || img.src.endsWith(LOGO)) {
				return;
			}
			img.src = LOGO;
			img.alt = APP_NAME;
			img.style.objectFit = "contain";
		});
	}

	function rebrandLabels(root) {
		const scope = root || document;
		const selectors =
			".widget-title, .widget-head .title, .app-title, .desk-sidebar-item-label, " +
			".sidebar-item-label, .shortcut-widget-box .caption, .page-title, .title-text, " +
			".module-link, .onboard-spotlight .title";
		scope.querySelectorAll(selectors).forEach((el) => {
			const raw = (el.textContent || "").trim();
			if (REBRAND_MAP[raw]) {
				el.textContent = REBRAND_MAP[raw];
			}
		});
		scope.querySelectorAll("[title]").forEach((el) => {
			const title = el.getAttribute("title");
			if (title && REBRAND_MAP[title]) {
				el.setAttribute("title", REBRAND_MAP[title]);
			}
		});
	}

	function rebrandTextNodes(root) {
		if (!root) {
			return;
		}
		const skip = new Set(["SCRIPT", "STYLE", "TEXTAREA", "INPUT"]);
		const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
		let node;
		while ((node = walker.nextNode())) {
			const parent = node.parentElement;
			if (!parent || skip.has(parent.tagName)) {
				continue;
			}
			let value = node.nodeValue;
			if (!value || !value.trim()) {
				continue;
			}
			let changed = false;
			Object.keys(REBRAND_MAP).forEach((key) => {
				if (value.includes(key)) {
					value = value.split(key).join(REBRAND_MAP[key]);
					changed = true;
				}
			});
			if (changed) {
				node.nodeValue = value;
			}
		}
	}

	function brandAppTiles(root) {
		(root || document)
			.querySelectorAll(
				".shortcut-widget-box, .widget.shortcut, [data-app-name='erpnext'], [data-route^='erpnext']"
			)
			.forEach((tile) => {
				const img = tile.querySelector("img");
				if (img && !img.src.endsWith(LOGO)) {
					img.src = LOGO;
					img.alt = APP_NAME;
				}
				const label = tile.querySelector(".widget-title, .caption, .ellipsis");
				if (label && label.textContent.trim() === "ERPNext") {
					label.textContent = APP_NAME;
				}
			});
	}

	function injectLauncherBadge() {
		const main = document.querySelector(".layout-main-section");
		if (!main || document.getElementById("agileclix-desk-badge")) {
			return;
		}
		const route = (window.location.pathname || "") + (window.location.hash || "");
		const onDeskHome =
			route === "/app" ||
			route.endsWith("/desk") ||
			route.includes("/desk/") &&
				!route.includes("/Form/") &&
				!route.includes("/List/");
		if (!onDeskHome) {
			return;
		}
		const badge = document.createElement("div");
		badge.id = "agileclix-desk-badge";
		badge.className = "agileclix-hero";
		badge.setAttribute("role", "status");
		const user = (typeof frappe !== "undefined" && frappe.session && frappe.session.user_fullname) || "";
		badge.innerHTML =
			'<img src="' +
			LOGO +
			'" alt="" class="agileclix-hero-logo" />' +
			'<span><span class="agileclix-hero-greet">Welcome back' +
			(user ? ", " + escapeHtml(user) : "") +
			'</span><strong class="agileclix-hero-title">' +
			APP_NAME +
			'</strong><span class="agileclix-hero-tagline">' +
			TAGLINE +
			"</span></span>";
		main.prepend(badge);
	}

	function rebrandString(value) {
		if (typeof value !== "string" || !value) {
			return value;
		}
		Object.keys(REBRAND_MAP).forEach((key) => {
			if (value.includes(key)) {
				value = value.split(key).join(REBRAND_MAP[key]);
			}
		});
		return value;
	}

	// Rebrand translated UI strings at the source so dialogs, toasts and titles never flash upstream names.
	function wrapTranslator() {
		if (typeof window.__ !== "function" || window.__.agileclixWrapped) {
			return;
		}
		const original = window.__;
		const wrapped = function () {
			return rebrandString(original.apply(this, arguments));
		};
		wrapped.agileclixWrapped = true;
		window.__ = wrapped;
	}

	function showAbout() {
		const dialog = new frappe.ui.Dialog({ title: __("About") });
		dialog.$body.html(
			'<div class="agileclix-about">' +
				'<img src="' +
				LOGO +
				'" alt="' +
				APP_NAME +
				'" />' +
				"<h3>" +
				APP_NAME +
				"</h3><p>" +
				TAGLINE +
				'</p><p class="text-muted">&copy; ' +
				new Date().getFullYear() +
				" " +
				PUBLISHER +
				"</p></div>"
		);
		dialog.show();
	}

	function overrideAbout() {
		if (frappe.ui && frappe.ui.misc) {
			frappe.ui.misc.about = showAbout;
		}
	}

	function setFavicon() {
		document.querySelectorAll("link[rel='icon'], link[rel='shortcut icon']").forEach((link) => {
			link.href = LOGO;
		});
		if (!document.querySelector("link[rel='icon']")) {
			const link = document.createElement("link");
			link.rel = "icon";
			link.href = LOGO;
			document.head.appendChild(link);
		}
	}

	function setTitle() {
		let title = document.title || "";
		Object.keys(REBRAND_MAP).forEach((key) => {
			title = title.split(key).join(REBRAND_MAP[key]);
		});
		document.title = title;
	}

	function apply() {
		markBranded();
		swapLogos(document);
		brandAppTiles(document);
		rebrandLabels(document);
		document.querySelectorAll(TEXT_ROOTS).forEach((el) => rebrandTextNodes(el));
		injectLauncherBadge();
		setFavicon();
		setTitle();
	}

	// Non-blocking brand loader for background requests; only shown when a request is slow enough to notice.
	const LOADER_DELAY_MS = 300;

	function initActivityLoader() {
		if (typeof jQuery === "undefined" || document.getElementById("ac-activity-loader")) {
			return;
		}
		const loader = document.createElement("div");
		loader.id = "ac-activity-loader";
		loader.className = "ac-loader";
		loader.setAttribute("role", "progressbar");
		loader.setAttribute("aria-label", "Loading");
		loader.setAttribute("aria-hidden", "true");
		document.body.appendChild(loader);

		let pending = 0;
		let showTimer = null;
		const setActive = (active) => {
			loader.classList.toggle("is-active", active);
			loader.setAttribute("aria-hidden", active ? "false" : "true");
		};

		jQuery(document).on("ajaxSend", () => {
			pending += 1;
			if (!showTimer) {
				showTimer = setTimeout(() => setActive(pending > 0), LOADER_DELAY_MS);
			}
		});
		jQuery(document).on("ajaxComplete", () => {
			pending = Math.max(0, pending - 1);
			if (pending === 0) {
				clearTimeout(showTimer);
				showTimer = null;
				setActive(false);
			}
		});
	}

	function scheduleApply() {
		if (applyScheduled) {
			return;
		}
		applyScheduled = true;
		requestAnimationFrame(() => {
			applyScheduled = false;
			apply();
		});
	}

	function observe() {
		const observer = new MutationObserver(() => scheduleApply());
		observer.observe(document.body, { childList: true, subtree: true });
	}

	if (typeof frappe !== "undefined" && frappe.ready) {
		wrapTranslator();
		frappe.ready(() => {
			wrapTranslator();
			overrideAbout();
			initActivityLoader();
			apply();
			observe();
			if (frappe.boot) {
				frappe.boot.app_name = APP_NAME;
				if (frappe.boot.sysdefaults) {
					frappe.boot.sysdefaults.app_name = APP_NAME;
				}
			}
			if (frappe.router && frappe.router.on) {
				frappe.router.on("change", scheduleApply);
			}
		});
	}

	if (document.readyState === "loading") {
		document.addEventListener("DOMContentLoaded", () => {
			apply();
			observe();
		});
	} else {
		apply();
		observe();
	}
})();
